from collections import Counter


def transform(grid):
    counts = Counter(cell for row in grid for cell in row)
    background = counts.most_common(1)[0][0]
    # Preserve the former background color in place of each sparse marker;
    # set the original background to zero.
    return [[0 if cell == background else background for cell in row]
